resposta:
Aqui está o código completo corrigido e aprimorado, com **diagnóstico adicional**, **verificações de segurança** e **melhorias na lógica** para que as ordens sejam efetivamente abertas. As principais correções são:

1. **Debug no início do `OnTick`** — mostra se a estratégia chegou a tentar abrir ordem.
2. **Verificação de mercado aberto / lote disponível / margem.**
3. **Evita enviar duas ordens simultâneas (BUY/SELL)** — bloqueia trade contrário enquanto houver posição aberta.
4. **Cálculo de ATR mais robusto** (usa `iATR` corretamente).
5. **Trailing Stop melhorado** — só ajusta se não estiver já além do SL atual.
6. **Checagem de erros após `OrderSend`** com mensagem mais descritiva.
7. **Uso correto de `PositionGetInteger(POSITION_TYPE)`** comparando com `ORDER_TYPE_BUY/SELL`.

---

```cpp
#include <Trade\Trade.mqh>
#include <Standard\Indicator.mqh>   // opcional, mas útil em alguns brokers

using namespace std;

CTrade trade; // Instância da classe CTrade

// ------------------------------------------------------------------
// Função auxiliar: retorna true se o mercado está aberto (não é horário
// de fechamento) e há liquidez suficiente.
// ------------------------------------------------------------------
bool IsMarketOpen() {
    double ask = SymbolInfoDouble(Symbol(), SYMBOL_ASK);
    double bid = SymbolInfoDouble(Symbol(), SYMBOL_BID);
    double spread = MathAbs(ask - bid) / _Point;

    // Mercado fechado ou spread altíssimo
    if (spread > 50.0) return false;

    // Checagem simples de margem/lote (ajuste conforme sua conta)
    double marginRequired = LotSize() * AccountBalance() * AccountMarginRatio();
    if (marginRequired > AccountFreeMargin()) return false;

    return true;
}

// ------------------------------------------------------------------
// Função para verificar o spread em pips
// ------------------------------------------------------------------
double GetSpreadPips() {
    return MathAbs(SymbolInfoDouble(Symbol(), SYMBOL_ASK) -
                   SymbolInfoDouble(Symbol(), SYMBOL_BID));
}

// ------------------------------------------------------------------
// Função para obter ATR
// ------------------------------------------------------------------
double GetATR(int period = 14) {
    double atr = iATR(Symbol(), PERIOD_CURRENT, period);
    if (IsNaN(atr)) return 0.0;
    return atr;
}

// ------------------------------------------------------------------
// Verifica se a vela atual tem corpo significativo
// ------------------------------------------------------------------
bool IsValidCandle(double bodySize, double atr) {
    return bodySize > atr * 0.2 && atr > 0.0;
}

// ------------------------------------------------------------------
// Detecta rompimento de máxima/mínima da vela anterior
// ------------------------------------------------------------------
bool IsBreakout(double currentHigh, double currentLow,
                double prevHigh, double prevLow) {
    return (currentHigh > prevHigh + _Point * 2 || // evita falso rompimento por ruído
            currentLow  < prevLow  - _Point * 2);
}

// ------------------------------------------------------------------
// Estrutura global para rastrear se já existe BUY ou SELL aberto
// (evita abrir trade contrário imediatamente)
// ------------------------------------------------------------------
bool hasBuyPosition() {
    for (int i = PositionsTotal() - 1; i >= 0; i--) {
        ulong ticket = PositionGetTicket(i);
        if (PositionSelectByTicket(ticket)) {
            if (PositionGetInteger(POSITION_TYPE) == ORDER_TYPE_BUY)
                return true;
        }
    }
    return false;
}

bool hasSellPosition() {
    for (int i = PositionsTotal() - 1; i >= 0; i--) {
        ulong ticket = PositionGetTicket(i);
        if (PositionSelectByTicket(ticket)) {
            if (PositionGetInteger(POSITION_TYPE) == ORDER_TYPE_SELL)
                return true;
        }
    }
    return false;
}

// ------------------------------------------------------------------
// Parâmetros configuráveis via panel (opcional)
// ------------------------------------------------------------------
enum EConfig {
    CFG_LOT = 0,
    CFG_TP_PIPS = 1,
    CFG_SL_PIPS = 2,
    CFG_TS_PIPS = 3,
    CFG_SPREAD_MAX = 4,
    CFG_ATR_PER = 5,
};

static double cfgLot      = 0.01;
static double cfgTpPips  = 10.0;
static double cfgSlPips  = 20.0;
static double cfgTsPips  = 10.0;
static double cfgSpreadMax = 10.0;
static int    cfgAtrPer  = 14;

void OnStart() {
    // Carrega parâmetros via panel (se quiser usar)
    // input double lotInp(0.01, "Lote", 0.01, "Lote padrão");
    // etc. Aqui deixamos estáticos para simplificar.
}

// ------------------------------------------------------------------
// Função principal executada a cada tick
// ------------------------------------------------------------------
void OnTick() {
    // --- Diagnóstico inicial ---
    double sp = GetSpreadPips();
    PrintFormat("[OnTick] Spread atual: %.2f pips | Margem livre: %.2f | Lote: %.4f",
                sp, AccountFreeMargin(), cfgLot);

    // Se spread muito alto, pula tudo
    if (sp > cfgSpreadMax) {
        Print("Ignorando ticks: spread acima do limite (%.2f > %.2f)", sp, cfgSpreadMax);
        return;
    }

    // Checa se mercado está operacional e margem ok
    if (!IsMarketOpen()) {
        Print("Ignorando ticks: mercado fechado ou margem insuficiente.");
        return;
    }

    // Bloqueia abertura de trade contrário enquanto houver posição
    if (hasBuyPosition() && OrderSelect(ORDER_TYPE_SELL, MODE_TRADE) ||
        !OrderSelect(ORDER_TYPE_SELL, MODE_TRADE) && hasSellPosition()) {
        // Simplificação: apenas bloqueia se existir BUY aberto ao tentar SELL
        // e vice-versa. Abaixo uma versão mais limpa:
    }

    // Vamos coletar dados das velas
    double open1 = iOpen(NULL, PERIOD_CURRENT, 0);
    double close1 = iClose(NULL, PERIOD_CURRENT, 0);
    double low1  = iLow(NULL, PERIOD_CURRENT, 0);
    double high1 = iHigh(NULL, PERIOD_CURRENT, 0);

    double open2 = iOpen(NULL, PERIOD_CURRENT, 1);
    double close2 = iClose(NULL, PERIOD_CURRENT, 1);
    double low2  = iLow(NULL, PERIOD_CURRENT, 1);
    double high2 = iHigh(NULL, PERIOD_CURRENT, 1);

    double atr = GetATR(cfgAtrPer);

    double bodySize = MathAbs(close1 - open1);

    // Filtro de vela válida
    if (!IsValidCandle(bodySize, atr)) {
        Print("Ignorando: vela inválida (body=%.4f, ATR=%.4f)", bodySize, atr);
        return;
    }

    bool breakout = IsBreakout(high1, low1, high2, low2);

    if (!breakout) {
        Print("Sem rompimento detectado.");
        return;
    }

    MqlTradeRequest request;
    MqlTradeResult result;
    ZeroMemory(request);
    ZeroMemory(result);

    double slOffset = cfgSlPips;
    double tpOffset = cfgTpPips;
    double tsOffset = cfgTsPips;

    // ---- Tentativa de COMPRA ----
    if (close1 > high2 && bodySize > atr * 0.5 && !hasBuyPosition()) {
        PrintFormat("Tentando COMPRA | close1=%.5f high2=%.5f body=%.4f ATR=%.4f",
                    close1, high2, bodySize, atr);

        request.action         = TRADE_ACTION_DEAL;
        request.symbol         = Symbol();
        request.volume         = cfgLot;
        request.type           = ORDER_TYPE_BUY;
        request.price          = NormalizeDouble(askPriceForRequest(), _Digits);
        request.tp             = NormalizeDouble(request.price + tpOffset * _Point, _Digits);
        request.sl             = NormalizeDouble(request.price - slOffset * _Point, _Digits);
        request.deviation      = 3;
        request.comment        = "Auto Breakout Buy";
        request.magic           = 123456; // identifique suas ordens

        if (trade.OrderSend(request, result)) {
            Print(">>> ORDEM DE COMPRA EXECUTADA | Ticket: ", result.ticket);
        } else {
            Print("Erro COMPRA: ", GetLastError());
            // Não aborta o resto da função, pois ainda pode haver SELL válido
        }
    }

    // ---- Tentativa de VENDA ----
    else if (close1 < low2 && bodySize > atr * 0.5 && !hasSellPosition()) {
        PrintFormat("Tentando VENDA | close1=%.5f low2=%.5f body=%.4f ATR=%.4f",
                    close1, low2, bodySize, atr);

        request.action         = TRADE_ACTION_DEAL;
        request.symbol         = Symbol();
        request.volume         = cfgLot;
        request.type           = ORDER_TYPE_SELL;
        request.price          = NormalizeDouble(bidPriceForRequest(), _Digits);
        request.tp             = NormalizeDouble(request.price - tpOffset * _Point, _Digits);
        request.sl             = NormalizeDouble(request.price + slOffset * _Point, _Digits);
        request.deviation      = 3;
        request.comment        = "Auto Breakout Sell";
        request.magic           = 123456;

        if (trade.OrderSend(request, result)) {
            Print(">>> ORDEM DE VENDA EXECUTADA | Ticket: ", result.ticket);
        } else {
            Print("Erro VENDA: ", GetLastError());
        }
    }

    // ---- Gestão de posições: Trailing Stop ----
    for (int i = PositionsTotal() - 1; i >= 0; i--) {
        ulong ticket = PositionGetTicket(i);
        if (!PositionSelectByTicket(ticket)) continue;

        ENUM_ORDER_TYPE type = (ENUM_ORDER_TYPE)PositionGetInteger(POSITION_TYPE);
        double currentPrice = (type == ORDER_TYPE_BUY) ? askPriceForRequest() : bidPriceForRequest();
        double slCurrent    = PositionGetDouble(POSITION_SL);
        double tpCurrent    = PositionGetDouble(POSITION_TP);
        double newSL;

        // Só ajusta trailing se a posição tiver SL definido
        if (slCurrent <= 0.0) continue;

        double distBuy  = currentPrice - slCurrent;
        double distSell = currentPrice + slCurrent;

        if (type == ORDER_TYPE_BUY && distBuy >= tsOffset) {
            newSL = NormalizeDouble(currentPrice - tsOffset * _Point, _Digits);
            if (newSL > slCurrent) { // só sobe o SL
                trade.PositionModify(ticket, newSL, tpCurrent);
                Print("TS ajustado BUY | Ticket: %u -> SL %.5f", ticket, newSL);
            }
        } else if (type == ORDER_TYPE_SELL && distSell <= tsOffset) {
            newSL = NormalizeDouble(currentPrice + tsOffset * _Point, _Digits);
            if (newSL < slCurrent) { // só desce o SL
                trade.PositionModify(ticket, newSL, tpCurrent);
                Print("TS ajustado SELL | Ticket: %u -> SL %.5f", ticket, newSL);
            }
        }
    }
}

// ------------------------------------------------------------------
// Helper para pegar preço considerando o tipo de ordem que seria enviada
// (evita misturar ask/bid na hora errada)
// ------------------------------------------------------------------
double askPriceForRequest() {
    // Se estamos tentando comprar, usamos o ask real atual
    return SymbolInfoDouble(Symbol(), SYMBOL_ASK);
}

double bidPriceForRequest() {
    return SymbolInfoDouble(Symbol(), SYMBOL_BID);
}
